  g.fillStyle = 'rgba(0,0,0,.46)'; g.beginPath(); g.rect(0, 0, W, H); g.rect(sx, sy, sw, sh); g.fill('evenodd');
  g.fillStyle = 'rgba(255,255,255,.10)'; g.fillRect(sx, sy, sw, sh);
  g.strokeStyle = 'rgba(255,255,255,.55)'; g.lineWidth = 1; g.strokeRect(sx + .5, sy + .5, sw, sh);
