    const hard = why === 'future' || why === 'cur', soft = why === 'fxc' || why === 'fxs';
    return Object.assign(it, { i: i, fp: dups[i].fp, why: why, cat: cat, side: fx && mode === 'split', dc: fx && mode === 'split' ? F : acc.cur, on: hard ? false : I.sel[i] != null ? I.sel[i] : (soft || !why) });
